function initializeAccounts(){let changed=false;if(!Array.isArray(data.accounts))data.accounts=[];const legacyJournal=data.accounts.some(a=>a.id==='manual:personal-journal'&&a.name==='Personal journal'&&a.platform==='Manual');if(legacyJournal){data.accounts=data.accounts.filter(a=>!(a.id==='manual:personal-journal'&&a.name==='Personal journal'&&a.platform==='Manual'));for(const t of data.trades)if(t.accountId==='manual:personal-journal'){for(const k of ['accountId','accountName','broker','server','platform','accountNumber'])delete t[k];changed=true}}for(const t of data.trades){if(t.accountId==='journal-only'){for(const k of ['accountId','accountName','broker','server','platform','accountNumber'])delete t[k];changed=true;continue}if(t.accountId&&data.accounts.some(a=>a.id===t.accountId&&a.archived))continue;let meta=null;if(t.accountId){meta=data.accounts.find(a=>a.id===t.accountId)||{id:t.accountId,name:t.accountName,broker:t.broker,server:t.server,platform:t.platform,accountNumber:t.accountNumber,currency:t.currency}}else if(['MT4','MT5'].includes(String(t.platform||'').toUpperCase())&&(t.accountNumber||t.account||t.sourceKey)){meta={name:t.accountName,broker:t.broker,server:t.server,platform:t.platform,accountNumber:t.accountNumber||t.account,currency:t.currency,source:'MetaTrader bridge'};changed=true}else continue;const a=registerAccount(meta);if(t.accountId!==a.id){t.accountId=a.id;changed=true}if(!t.accountName&&a.name){t.accountName=a.name;changed=true}if(!t.platform&&a.platform){t.platform=a.platform;changed=true}if(!t.accountNumber&&a.accountNumber){t.accountNumber=a.accountNumber;changed=true}if(!t.broker&&a.broker){t.broker=a.broker;changed=true}if(!t.server&&a.server){t.server=a.server;changed=true}}data.accountScope=data.accounts.some(a=>a.id===data.accountScope&&!a.archived)?data.accountScope:'all';if(changed)save()}
