function analysisPage(){const all=accountTrades().filter(t=>t.status!=='Open'&&t.exit!==''&&t.exit!=null),now=Date.now(),periodMs={'Today':null,'7 Days':7*864e5,'30 Days':30*864e5,'3 Months':90*864e5,'1 Year':365*864e5,'All Time':Infinity}[performanceFilters.period]??30*864e5;let a=all.filter(t=>performanceFilters.period==='Today'?parseDate(t.closed||t.opened)>=kolkataMidnight():parseDate(t.closed||t.opened).getTime()>=now-periodMs);if(performanceFilters.outcome==='Winners')a=a.filter(t=>pnl(t)>0);if(performanceFilters.outcome==='Losers')a=a.filter(t=>pnl(t)<0);const w=a.filter(t=>pnl(t)>0),l=a.filter(t=>pnl(t)<0),net=a.reduce((x,t)=>x+pnl(t),0),grossWin=w.reduce((x,t)=>x+pnl(t),0),grossLoss=Math.abs(l.reduce((x,t)=>x+pnl(t),0)),factor=grossLoss? (grossWin/grossLoss).toFixed(2):grossWin?'∞':'—',long=a.filter(t=>t.direction==='Long'),short=a.filter(t=>t.direction==='Short'),symbols=[...new Set(a.map(t=>t.symbol))].map(s=>({s,v:a.filter(t=>t.symbol===s).reduce((x,t)=>x+pnl(t),0)})).sort((x,y)=>y.v-x.v);return `<div class="performance-page"><div class="analysis-titlebar"><div class="page-head"><div><p class="eyebrow">TRADE PERFORMANCE</p><h2>Performance analytics</h2><p>Showing ${escapeHtml(performanceFilters.period)} · ${escapeHtml(performanceFilters.outcome)} · ${accountScope==='all'?'All accounts':escapeHtml(accountDisplay(accountById(accountScope)||{}))} · ${escapeHtml(timezoneDescription())}.</p></div></div><div class="analysis-controls"><div class="control-group"><span>TIME PERIOD</span>${['Today','7 Days','30 Days','3 Months','1 Year','All Time'].map(x=>`<button class="small-btn ${performanceFilters.period===x?'selected':''}" data-performance-period="${x}">${x}</button>`).join('')}</div><div class="control-group"><span>FILTER BY</span>${['All Trades','Winners','Losers'].map(x=>`<button class="small-btn ${performanceFilters.outcome===x?'selected':''}" data-performance-outcome="${x}">${x}</button>`).join('')}</div></div></div><div class="grid metrics analysis-metrics">${metric('TOTAL BOOKED P&L',money(net),`${a.length} closed trades · open P&L excluded`,'◈',net>=0?'positive':'negative')}${metric('WIN RATE',`${a.length?Math.round(w.length/a.length*100):0}%`,`${w.length} wins · ${l.length} losses`,'↗')}${metric('PROFIT FACTOR',factor,'Gross wins / losses','◎')}${metric('EXPECTANCY',money(a.length?net/a.length:0),'Expected profit per trade','⌁')}</div><section class="card analysis-curve"><div class="card-heading"><div><h3>Equity curve</h3><small>Cumulative P&amp;L progression</small></div><div class="segmented">${['Equity','Drawdown'].map(x=>`<button class="${performanceFilters.curve===x?'selected':''}" data-curve="${x}">${x}</button>`).join('')}</div></div>${chartSvg(a,performanceFilters.curve)}<div class="curve-stats">${[['AVG WIN',w.length?money(avg(w.map(pnl))):money(0)],['AVG LOSS',l.length?money(avg(l.map(pnl))):money(0)],['BEST TRADE',money(Math.max(0,...a.map(pnl)))],['WORST TRADE',money(Math.min(0,...a.map(pnl)))],['WIN STREAK',streakCount(a,true)],['LOSS STREAK',streakCount(a,false)],['RISK:REWARD',a.some(t=>t.rrRisk!==''&&t.rrRisk!=null&&t.rrReward!==''&&t.rrReward!=null&&Number(t.rrRisk)>0&&Number(t.rrReward)>=0)?`1:${avg(a.filter(t=>t.rrRisk!==''&&t.rrRisk!=null&&t.rrReward!==''&&t.rrReward!=null&&Number(t.rrRisk)>0&&Number(t.rrReward)>=0).map(t=>Number(t.rrReward)/Number(t.rrRisk))).toFixed(2)}`:'—'],['OPEN TRADES',String(accountTrades().filter(t=>t.status==='Open').length)]].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div></section><section class="card distribution"><div class="card-heading"><h3>Win / loss distribution</h3><small>${w.length} winners · ${l.length} losers</small></div><div class="distribution-bar"><span style="width:${a.length?w.length/a.length*100:0}%">${w.length?`${w.length}W`:''}</span><i style="width:${a.length?l.length/a.length*100:0}%"></i></div><div class="distribution-stats"><div><small>GROSS PROFIT</small><b class="positive">${money(grossWin)}</b></div><div><small>GROSS LOSS</small><b class="negative">${money(-grossLoss)}</b></div><div><small>NET RESULT</small><b>${money(net)}</b></div></div></section>${yourStatsSection(a,w,l)}<div class="grid analysis-columns"><section class="card"><h3>Long vs short</h3><small>Performance by trade direction</small>${[['Long',long],['Short',short]].map(([d,x])=>`<div class="direction-row"><b>${d}</b><span>${x.length} trades · ${a.length?Math.round(x.length/a.length*100):0}%</span><strong>${money(x.reduce((z,t)=>z+pnl(t),0))}</strong></div>`).join('')}</section><section class="card"><h3>Day performance</h3><small>Best trading days (${escapeHtml(timezoneDisplayName())} time)</small>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=>{const x=a.filter(t=>{const weekday=new Intl.DateTimeFormat('en-US',{timeZone:APP_TZ,weekday:'short'}).format(parseDate(t.closed||t.opened));return ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].indexOf(weekday)===i});return `<div class="day-row"><span>${d}</span><i><b style="width:${Math.max(0,Math.abs(x.reduce((z,t)=>z+pnl(t),0))/Math.max(1,...a.map(t=>Math.abs(pnl(t))))*100)}%"></b></i><strong>${x.length?money(x.reduce((z,t)=>z+pnl(t),0)):'—'}</strong></div>`}).join('')}</section><section class="card"><h3>Top symbols</h3><small>Best performing assets</small>${symbols.slice(0,5).map(x=>`<div class="symbol-row"><b>${escapeHtml(x.s)}</b><span>${a.filter(t=>t.symbol===x.s).length} trades</span><strong>${money(x.v)}</strong></div>`).join('')||'<div class="empty-state">No closed trades in this period</div>'}</section></div><section class="card session-performance"><h3>Session performance</h3><small>Asia · London · New York · ${escapeHtml(timezoneDisplayName())} local time</small><div class="session-strip"><span>Asia <small>00:00–08:00</small></span><span>London <small>08:00–13:00</small></span><span>New York <small>13:00–22:00</small></span><span>Asia <small>22:00–24:00</small></span><i>NOW</i></div></section></div>`}
function streakCount(items,win){let best=0,current=0;for(const t of [...items].sort((a,b)=>parseDate(a.closed||a.opened)-parseDate(b.closed||b.opened))){const yes=win?pnl(t)>0:pnl(t)<0;current=yes?current+1:0;best=Math.max(best,current)}return best}
function tradeAnalysisPage(){let all=accountTrades().filter(t=>t.status!=='Open'&&t.exit!==''&&t.exit!=null);if(tradeAnalysisFilter==='Winners')all=all.filter(t=>pnl(t)>0);if(tradeAnalysisFilter==='Losers')all=all.filter(t=>pnl(t)<0);if(tradeAnalysisFilter==='Break-even')all=all.filter(t=>pnl(t)===0);if(tradeAnalysisPeriod!=='All Time'){const cutoff=tradeAnalysisPeriod==='This Month'?zonedWallTimeToDate(zonedParts().year,zonedParts().month,1):new Date(Date.now()-30*864e5);all=all.filter(t=>parseDate(t.closed||t.opened)>=cutoff)}all=all.filter(t=>`${t.symbol} ${t.direction} ${t.tags||''}`.toLowerCase().includes(analysisSearch.toLowerCase()));if(!all.length)return `<div class="page-head"><div><p class="eyebrow">TRADE ANALYSIS</p><h2>Trade analysis</h2></div></div><div class="empty-state"><b>No matching closed trades</b>Closed trades appear here with an automatic quality score and journal review.</div>`;const t=all.find(x=>x.id===selectedAnalysisTradeId)||all[0],q=qualityScore(t),net=reportedPnl(t)??pnl(t),label=q.total>=80?'Excellent':q.total>=60?'Good':q.total>=40?'Average':'Needs Work',fields=[['Profitability',q.profitability,30],['Execution',q.execution,40],['Journal',q.journal,20],['Rating',q.rating,10]],fullJournal=Boolean(t.journalPre||t.journalPost||t.emotions||t.lesson||t.tags||t.preScreenshot||t.postScreenshot||(t.qualityChecks||[]).some(x=>x.checked)),checks=q.qualityFlags;return `<div class="trade-analysis-page"><div class="page-head"><div><p class="eyebrow">ANALYSIS · AUTOMATIC SCORING</p><h2>Trade analysis</h2><p>Review each result, trade quality, and journal entry.</p></div><button class="button" data-view-link="journal">Open journal workspace →</button></div><div class="analysis-review-layout"><aside class="card analysis-trade-list"><h3>Trade analysis</h3><div class="analysis-tabs">${[['All',accountTrades().filter(x=>x.status!=='Open'&&x.exit!==''&&x.exit!=null).length],['Winners',accountTrades().filter(x=>x.status!=='Open'&&pnl(x)>0).length],['Losers',accountTrades().filter(x=>x.status!=='Open'&&pnl(x)<0).length],['Break-even',accountTrades().filter(x=>x.status!=='Open'&&pnl(x)===0).length]].map(([n,c])=>`<button class="${tradeAnalysisFilter===n?'selected':''}" data-analysis-filter="${n}">${n} <b>${c}</b></button>`).join('')}</div><input class="analysis-search" type="search" placeholder="Search symbol…" value="${escapeHtml(analysisSearch)}" data-analysis-search><label class="analysis-period">Period<select data-analysis-period><option ${tradeAnalysisPeriod==='This Month'?'selected':''}>This Month</option><option ${tradeAnalysisPeriod==='Last 30 Days'?'selected':''}>Last 30 Days</option><option ${tradeAnalysisPeriod==='All Time'?'selected':''}>All Time</option></select></label><div class="analysis-choice-list">${all.map(x=>`<button class="analysis-trade-choice ${x.id===t.id?'selected':''}" data-select-analysis="${x.id}"><b>${escapeHtml(x.symbol)}</b><strong class="${pnl(x)>=0?'positive':'negative'}">${money(reportedPnl(x)??pnl(x),x.currency)}</strong><small>${escapeHtml(x.direction)} · ${shortStamp(x.opened)}</small><span>@ ${escapeHtml(x.entry)}</span></button>`).join('')}</div></aside><main class="analysis-selected"><section class="card selected-trade-banner"><div class="selected-symbol"><span class="symbol-mark">◉</span><div><h3>${escapeHtml(t.symbol)} <span class="pill ${net>=0?'positive':'negative'}">${net>0?'Winner':net<0?'Loser':'Break-even'}</span> <span class="pill score-pill">Score ${q.total}</span></h3><p><span class="direction-label ${t.direction==='Long'?'direction-long':'direction-short'}">${escapeHtml(t.direction)}</span> · ${shortStamp(t.opened)} · Held ${durationLabel(t)}</p></div></div><div class="net-pnl"><small>NET P&amp;L</small><b>${money(net)}</b></div></section><section class="card trade-facts">${[['ENTRY PRICE',t.entry],['EXIT PRICE',t.exit],['QUANTITY',t.size],['PRICE MOVE',`${pips(t)==null?'—':`${pips(t)>0?'+':''}${pips(t).toFixed(1)} pips`}`],['DURATION',durationLabel(t)]].map(([k,v])=>`<div><small>${k}</small><b>${escapeHtml(v??'—')}</b></div>`).join('')}</section><section class="card replay-panel"><div class="card-heading"><div><h3>Trade simulation</h3><small>Candle replay around your entry &amp; exit</small></div><button class="small-btn" data-view-link="journal">Open chart ↗</button></div><div class="analysis-replay-chart" data-journal-chart="${escapeHtml(t.symbol)}"><div class="empty-state"><b>Trade replay chart</b>Chart bars appear when the MT4/MT5 bridge supplies candles for this symbol.</div></div><small class="muted">Manual entries do not contain historical candle data by themselves.</small></section><div class="analysis-review-cards"><section class="card journal-entry-summary"><div class="card-heading"><h3>▤ Journal Entry</h3><span class="pill ${fullJournal?'':'open'}">${fullJournal?'Journaled':'Pending review'}</span></div><div class="quality-flag-summary">${checks.map(c=>`<div class="quality-flag ${c.checked?'checked':''}"><span>${c.checked?'✓':'○'}</span>${escapeHtml(c.label)}</div>`).join('')}</div><div class="journal-rating-summary"><span>Rating</span><b>${'★'.repeat(Math.max(0,Math.min(10,Number(t.rating)||0)))}<i>${'★'.repeat(10-Math.max(0,Math.min(10,Number(t.rating)||0)))}</i></b><span>${Number(t.rating)||0}/10</span></div>${t.lesson?`<div class="lesson-summary"><small>LESSONS LEARNED</small><p>${escapeHtml(t.lesson)}</p></div>`:`<p class="muted">Add your review, emotions, lessons, tags, and screenshots in Journal.</p>`}<button class="full-journal-button" data-view-link="journal">View full journal ›</button></section><section class="card trade-quality-card"><div class="card-heading"><h3>◎ Trade Quality</h3><span class="pill quality-grade grade-${label.toLowerCase().replaceAll(' ','-')}">${q.total} · ${label}</span></div><div class="quality-score-layout"><div class="quality-score-ring" style="--score:${q.total}"><b>${q.total}</b></div><div class="quality-breakdown">${fields.map(([n,v,m])=>`<div class="quality-score-row"><span>${n}</span><i><b style="width:${Math.min(100,v/m*100)}%"></b></i><small>${v}/${m}</small></div>`).join('')}</div></div><details class="score-explanation" open><summary>How is this calculated?</summary><div><b>Profitability (30 pts)</b><span>Win 30 · Break-even 15 · Loss 0</span></div><div><b>Execution (40 pts)</b><span>10 points each for the four journal quality checks</span></div><div><b>Journal (20 pts)</b><span>5 points each for pre-review, post-review, emotions, and lessons</span></div><div><b>Rating (10 pts)</b><span>Your self-rating from 1 to 10</span></div></details><div class="score-legend"><span>80+ Excellent</span><span>60+ Good</span><span>40+ Average</span><span>&lt;40 Needs work</span></div></section></div></main></div></div>`}
function economicCalendarPage(){return `<div class="page-head"><div><p class="eyebrow">MARKET EVENTS</p><h2>Economic calendar</h2><p>ForexFactory sourced events · displayed in ${escapeHtml(timezoneDescription())}.</p></div><div class="calendar-page-actions"><span id="calendar-updated">${calendarStale?'Saved feed':`Updated ${escapeHtml(calendarUpdated||'recently')}`}</span><button class="button" data-refresh-calendar>↻ Refresh</button></div></div><section class="card calendar-card"><div class="calendar-feed-note"><span class="live-indicator ${calendarStale?'stale':''}"></span><span id="calendar-feed-status">${navigator.onLine?(calendarStale?'Connecting to live feed…':'Live feed · '+escapeHtml(calendarUpdated||'updated')):'Offline · showing saved calendar data'}</span><small>Actual, forecast and previous values update as the source publishes them.</small></div><div class="calendar-filters"><label>Country / currency<select data-calendar-currency><option value="ALL">All currencies</option>${[['USD','United States · USD'],['EUR','Euro area · EUR'],['GBP','United Kingdom · GBP'],['JPY','Japan · JPY'],['AUD','Australia · AUD'],['CAD','Canada · CAD'],['CHF','Switzerland · CHF'],['NZD','New Zealand · NZD'],['CNY','China · CNY'],['INR','India · INR']].map(([v,n])=>`<option value="${v}" ${calendarCurrency===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Impact<select data-calendar-impact>${['All','High','Medium','Low','Holiday'].map(x=>`<option ${calendarImpact===x?'selected':''}>${x}</option>`).join('')}</select></label><span class="calendar-filter-count" id="calendar-filter-count"></span></div><div id="economic-calendar-state" class="empty-state" ${calendarEvents.length?'hidden':''}>${calendarEvents.length?'':'Loading calendar events…'}</div><div id="economic-calendar-list" class="economic-events"></div><p class="calendar-source-note">Live schedule and released values sourced from <a href="https://pipatlas.com/api-docs" target="_blank" rel="noreferrer">PipAtlas</a>, which attributes the calendar to ForexFactory. Event links open the source listing when available.</p></section>`}
function renderEconomicEvents(){const box=document.querySelector('#economic-calendar-state'),list=document.querySelector('#economic-calendar-list'),count=document.querySelector('#calendar-filter-count');if(!list)return;const events=calendarEvents.filter(e=>(calendarCurrency==='ALL'||String(e.currency||'').toUpperCase()===calendarCurrency)&&(calendarImpact==='All'||String(e.impact||'').toLowerCase()===calendarImpact.toLowerCase())).sort((a,b)=>new Date(a.date)-new Date(b.date));if(count)count.textContent=`${events.length} events`;if(box){box.hidden=events.length>0;box.textContent=calendarEvents.length?'No events match these filters.':(navigator.onLine?'No events available.':'Offline · no saved calendar yet')}list.innerHTML=events.map(e=>{const impact=String(e.impact||'Low'),stamp=new Date(e.date).toLocaleString(undefined,{timeZone:APP_TZ,weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}),source=typeof e.url==='string'&&e.url.startsWith('https://www.forexfactory.com/')?e.url:'https://www.forexfactory.com/calendar';return `<article class="economic-event impact-${escapeHtml(impact.toLowerCase())}"><span class="event-impact">${escapeHtml(impact)}</span><time>${escapeHtml(stamp)} ${timezoneAbbreviation()}</time><b><a href="${escapeHtml(source)}" target="_blank" rel="noreferrer">${escapeHtml(e.currency||'ALL')} · ${escapeHtml(e.name||'Event')} ↗</a></b><div class="event-values"><span><small>ACTUAL</small><strong>${escapeHtml(e.actual||'—')}</strong></span><span><small>FORECAST</small><strong>${escapeHtml(e.forecast||'—')}</strong></span><span><small>PREVIOUS</small><strong>${escapeHtml(e.previous||'—')}</strong></span></div></article>`}).join('')}
async function loadEconomicCalendar(){const box=document.querySelector('#economic-calendar-state');if(!box)return;box.hidden=false;box.textContent=calendarEvents.length?'Refreshing live calendar…':'Loading live calendar…';try{const r=await fetch('https://pipatlas.com/api/calendar',{cache:'no-store'});if(!r.ok)throw Error(`HTTP ${r.status}`);const d=await r.json();if(!Array.isArray(d.events))throw Error('Calendar payload has no event list');calendarEvents=d.events;calendarStale=Boolean(d.stale);calendarUpdated=d.updated?new Date(d.updated).toLocaleString(undefined,{timeZone:APP_TZ,hour:'numeric',minute:'2-digit',month:'short',day:'numeric'}):new Intl.DateTimeFormat(undefined,{timeZone:APP_TZ,hour:'numeric',minute:'2-digit'}).format(new Date());try{localStorage.setItem(calendarCacheKey,JSON.stringify(calendarEvents))}catch{}const status=document.querySelector('#calendar-feed-status'),updated=document.querySelector('#calendar-updated');if(status)status.textContent=calendarStale?'Source returned its saved copy · data may be delayed':'Live feed · refreshed successfully';if(updated)updated.textContent=`Updated ${calendarUpdated}`;document.querySelector('.live-indicator')?.classList.toggle('stale',calendarStale);renderEconomicEvents()}catch{calendarStale=true;const status=document.querySelector('#calendar-feed-status'),updated=document.querySelector('#calendar-updated');if(status)status.textContent=calendarEvents.length?'Offline or feed unavailable · showing last saved data':'Feed unavailable · check your connection';if(updated)updated.textContent=calendarEvents.length?`Last saved ${calendarUpdated||'earlier'}`:'Not updated';renderEconomicEvents()}}
function backtestingPage(){return `<div class="page-head"><div><p class="eyebrow">STRATEGY SIMULATION</p><h2>Backtesting</h2><p>Load historical OHLC data, then simulate a moving-average crossover.</p></div><span class="pill">${data.bridge.connected?'MT4/MT5 connected · OHLC CSV required':'Connect MT4/MT5 for broker specs'}</span></div><div class="grid two-col"><section class="card"><h3>Historical price data</h3><p class="muted">The bridge currently syncs trades and specifications. Export candle history from MT4/MT5 as CSV (date, open, high, low, close).</p><label class="file-drop">Choose OHLC CSV<input type="file" id="ohlc-file" accept=".csv,text/csv"></label><div class="form-grid" style="margin-top:14px"><label>Symbol<select id="test-symbol" aria-label="Backtest symbol">${symbolOptions()}</select></label><label>Fast average<input id="fast-period" type="number" value="10"></label><label>Slow average<input id="slow-period" type="number" value="30"></label><label>Starting balance<input id="start-balance" type="number" value="10000"></label><label>Lots<input id="test-size" type="number" value="1" step="any"></label><label>Pip size<input id="test-pip-size" type="number" step="any"></label><label>Cash / pip / lot<input id="test-pip-value" type="number" step="any"></label><label>Spread pips<input id="test-spread" type="number" value="0"></label><label>Commission / lot / side<input id="test-commission" type="number" value="0"></label></div><button class="primary-button" id="run-backtest">Run backtest</button></section><section class="card" id="backtest-results"><h3>Results</h3><div class="empty-state">Load price data to begin.</div></section></div>`}
function toolsPage(){if(!LOCAL_BRIDGE_AVAILABLE)return `<div class="page-head"><div><h2>MT4 / MT5 connection</h2><p>MetaTrader sync runs through the private local bridge on your PC.</p></div></div><section class="card hosted-bridge-note"><h3>Use the local journal on your trading PC</h3><p>MetaTrader connects only to the bridge running on this computer. Account data and the pairing token stay local.</p><ol><li>Open this journal on the same PC as MetaTrader.</li><li>Keep the local TradeLog service running.</li><li>Set up each terminal from Connect MT4 / MT5 on the local journal.</li></ol><p>Use CSV export/import to move records between devices.</p></section>`;const profiles=data.accounts.filter(a=>a.platform==='MT4'||a.platform==='MT5'||a.source==='MetaTrader bridge');return `<div class="page-head connection-page-head"><div><h2>Connect MT4 / MT5</h2><p>Add an account profile, then set up its terminal below.</p></div><label class="connection-scope"><span>Account</span><select data-bridge-scope><option value="all" ${accountScope==='all'?'selected':''}>All accounts</option>${data.accounts.map(a=>`<option value="${escapeHtml(a.id)}" ${accountScope===a.id?'selected':''}>${escapeHtml(accountDisplay(a))}</option>`).join('')}</select></label></div><section class="card connection-add-card"><div class="card-heading"><div><h3>Add an account</h3><small>Use the login number and exact broker server name shown in MetaTrader.</small></div></div><form id="mt-account-form" class="connect-account-form"><label>Platform<select name="platform"><option value="MT5" selected>MT5</option><option value="MT4">MT4</option></select></label><label>Name<input name="name" required placeholder="AquaFunded account"></label><label>Broker server<input name="server" required placeholder="BrokerName-Live"></label><label>Login number<input name="accountNumber" required inputmode="numeric" placeholder="12345678"></label><label>Starting balance (${escapeHtml(data.accountCurrency)})<input name="balance" type="number" min="0" step="any" placeholder="Optional"></label><button class="primary-button" type="submit">Add account</button></form><p class="connection-note">TradeLog never asks for your broker password. The starting balance is only a reference until a live terminal sync updates it.</p></section><section class="card connection-steps-card"><div class="card-heading"><div><h3>Set up each terminal</h3><small>Repeat these steps for every account you want to sync.</small></div><a class="small-btn" href="./bridge/" target="_blank" rel="noreferrer">Detailed guide</a></div><ol class="connection-step-list"><li><b>Allow the local address</b><span>In MT4/MT5: Tools → Options → Expert Advisors → WebRequest. Add <code>http://127.0.0.1:4188</code>.</span></li><li><b>Add the TradeLog bridge EA</b><span>Compile the MT4 or MT5 file in MetaEditor and attach it to a chart in that account.</span></li><li><b>Enable sync</b><span>Paste the local pairing token into the EA settings and turn on Algo Trading / AutoTrading.</span></li><li><b>Wait for the first heartbeat</b><span>The account changes to Connected and refreshes about every 15 seconds. Sync is read-only and cannot place or modify orders.</span></li></ol></section><section class="card connected-accounts-card"><div class="card-heading"><div><h3>Accounts and sync status</h3><small>Each account keeps its own trades, balance, and statistics.</small></div></div>${profiles.length?`<div class="connected-account-list">${profiles.map(a=>`<article class="connected-account-row"><span class="connected-indicator ${a.connected?'is-connected':''}" aria-hidden="true"></span><div class="connected-account-copy"><b>${escapeHtml(a.name)}</b><small>${escapeHtml([a.platform,a.server].filter(Boolean).join(' · '))} · Login ${escapeHtml(a.accountNumber||'—')}</small></div><span class="connected-account-balance"><b>${a.balance!==''&&a.balance!=null?money(a.balance,a.currency):'Balance pending'}</b><small>${a.connected?'Connected · balance updates every 15 sec':a.balanceAsOf?'Offline · last synced balance retained':a.balance!==''&&a.balance!=null?'Starting balance · waiting for first sync':'Not connected yet'}</small></span><button class="small-btn" type="button" data-set-account-scope="${escapeHtml(a.id)}">View stats</button></article>`).join('')}</div>`:`<div class="empty-state"><b>No account profiles yet</b>Add an account above, then attach the bridge EA to its MT4/MT5 terminal.</div>`}</section>`}function tradeInsightsPage(){const closed=accountTrades().filter(t=>t.status!=='Open'&&t.exit!==''&&t.exit!=null&&cashKnown(t));const total=closed.length,wins=closed.filter(t=>pnl(t)>0),losses=closed.filter(t=>pnl(t)<0),winRate=total?Math.round(wins.length/total*100):0;const bySymbol=[...new Set(closed.map(t=>t.symbol))].map(symbol=>{const rows=closed.filter(t=>t.symbol===symbol);return{symbol,rows,net:rows.reduce((s,t)=>s+pnl(t),0)}}).filter(x=>x.rows.length>=3).sort((a,b)=>b.net-a.net);const bySide=['Long','Short'].map(side=>{const rows=closed.filter(t=>t.direction===side);return{side,rows,average:rows.length?rows.reduce((s,t)=>s+pnl(t),0)/rows.length:0}}).filter(x=>x.rows.length>=3).sort((a,b)=>b.average-a.average);const journaled=closed.filter(t=>t.journalPre||t.journalPost||t.emotions||t.lesson||t.tags).length;const bullets=[];if(total>=3)bullets.push(`<li><b>Win rate:</b> ${winRate}% across ${total} closed trades. ${winRate>=50?'More than half of recorded trades closed positive.':'Fewer than half of recorded trades closed positive.'}</li>`);if(bySymbol.length){const best=bySymbol[0],worst=bySymbol.at(-1);bullets.push(`<li><b>Symbol sample:</b> ${escapeHtml(best.symbol)} has the strongest net result (${money(best.net)}) from ${best.rows.length} trades.${worst.symbol!==best.symbol?` ${escapeHtml(worst.symbol)} is lowest (${money(worst.net)}) from ${worst.rows.length} trades.`:''}</li>`)}if(bySide.length>1&&bySide[0].side!==bySide.at(-1).side)bullets.push(`<li><b>Direction sample:</b> ${bySide[0].side} averages ${money(bySide[0].average)} per trade across ${bySide[0].rows.length}; ${bySide.at(-1).side} averages ${money(bySide.at(-1).average)} across ${bySide.at(-1).rows.length}.</li>`);if(total)bullets.push(`<li><b>Journal coverage:</b> ${Math.round(journaled/total*100)}% (${journaled}/${total}) of closed trades have at least one journal field filled in.</li>`);return `<div class="page-head"><div><h2>Trade insights</h2><p>Evidence-based patterns calculated from your saved trade history.</p></div><span class="pill">Private · calculated on this device</span></div><section class="card insight-report"><div class="card-heading"><h3>Your trade patterns</h3><span class="muted">${total} trades with known cash P&amp;L</span></div>${total>=3?`<ul class="insight-list">${bullets.join('')}</ul>`:`<div class="empty-state"><b>More history needed</b>Insights appear after at least 3 closed trades with a known cash P&amp;L. Add notes and journal reviews to make the analysis more useful.</div>`}</section><section class="card ai-availability"><h3>AI trade insights</h3><p>These findings are transparent statistics, not generated AI. A real AI review needs an AI provider and secure server setup. That would send selected trade data to that provider, so it will remain off until you choose and enable it.</p><button class="button" data-view-link="trade-analysis">Open trade quality analysis →</button></section>`}
function settingsPage(){const activeAccounts=data.accounts.filter(x=>!x.archived),archivedAccounts=data.accounts.filter(x=>x.archived),a=activeAccounts.find(x=>x.id===editingAccountId)||activeAccounts[0];if(a)editingAccountId=a.id;return `<div class="page-head"><div><h2>Settings</h2><p>Manage trading accounts, balance updates, and your local journal profile.</p></div><button class="primary-button" id="new-account">＋ Add account</button></div><section class="card profile-settings"><div class="card-heading"><div><h3>Your profile</h3><small>Personalize the name, short bio, and picture shown in your workspace.</small></div></div><form id="profile-form" class="form-grid profile-form"><label>Name<input name="profileName" maxlength="48" value="${escapeHtml(data.profile.name)}" placeholder="Your name" required></label><label>Bio<textarea name="profileBio" rows="2" maxlength="120" placeholder="A short line about you">${escapeHtml(data.profile.bio)}</textarea></label><div class="profile-photo-row"><div class="avatar profile-avatar-preview" id="profile-avatar-preview">${data.profile.photo?`<img src="${escapeHtml(data.profile.photo)}" alt="">`:`<span>${escapeHtml(String(data.profile.name||'M').trim().charAt(0).toUpperCase()||'M')}</span>`}</div><div class="profile-photo-controls"><label for="profile-photo">Profile picture</label><input id="profile-photo" type="file" accept="image/*"><small>Image is resized and saved in this browser only.</small><button type="button" class="small-btn" data-remove-profile-photo>Remove picture</button></div></div><div class="wide modal-foot"><button type="submit" class="primary-button">Save profile</button></div></form></section><section class="card account-settings"><div class="card-heading"><div><h3>Trading accounts</h3><small>Balances from MT4/MT5 update from the terminal heartbeat. Enter a balance for manual or CSV accounts to have each new booked trade adjust it by realized P&amp;L.</small></div></div>${a?`<form id="account-edit-form" class="form-grid account-edit-form"><input type="hidden" name="accountId" value="${escapeHtml(a.id)}"><label>Account profile<select data-account-edit>${activeAccounts.map(x=>`<option value="${escapeHtml(x.id)}" ${x.id===a.id?'selected':''}>${escapeHtml(accountDisplay(x))}</option>`).join('')}</select></label><label>Platform<input name="platform" value="${escapeHtml(a.platform||'')}" placeholder="MT5, MT4, Manual"></label><label>Account name<input name="name" value="${escapeHtml(a.name||'')}" placeholder="AquaFunded account"></label><label>Broker<input name="broker" value="${escapeHtml(a.broker||'')}" placeholder="Broker or prop firm"></label><label>Server<input name="server" value="${escapeHtml(a.server||'')}" placeholder="Optional server name"></label><label>Account number<input name="accountNumber" value="${escapeHtml(a.accountNumber||'')}" placeholder="Trading login number"></label><label>Account currency<input name="currency" value="${escapeHtml(a.currency||'USD')}" maxlength="8"></label><label>Balance<input name="balance" type="number" step="any" value="${escapeHtml(a.balance??'')}" placeholder="Enter current balance"></label><label>Balance as of<input name="balanceAsOf" type="date" value="${escapeHtml(a.balanceAsOf||'')}"></label><div class="wide account-form-note">${a.source==='MetaTrader bridge'?'This account balance is reported by MT4/MT5 and refreshes while the terminal bridge is connected.': 'For a manual/CSV account, this is the current balance baseline. Saving a closed trade will add or subtract its realized P&amp;L automatically.'}</div><div class="wide modal-foot account-actions"><button class="small-btn danger" type="button" data-remove-account="${escapeHtml(a.id)}">Remove account link</button><button class="primary-button" type="submit">Save account details</button></div></form>`:'<div class="empty-state">No active account profiles. Add one or restore an archived account below.</div>'}${archivedAccounts.length?`<div class="archived-account-list"><h4>Removed account links</h4><p>Trade history is preserved in All Accounts. Restore a link here if you reconnect it.</p>${archivedAccounts.map(x=>`<div class="archived-account-row"><span>${escapeHtml(accountDisplay(x))}</span><button class="small-btn" type="button" data-restore-account="${escapeHtml(x.id)}">Restore</button></div>`).join('')}</div>`:''}</section><section class="card"><div class="setting-row theme-setting-row"><div><b>Appearance</b><p>Choose the interface theme.</p></div><div class="theme-choices" role="group" aria-label="Appearance theme">${[['dark','Dark'],['light','Light'],['glass','Glossy Grey']].map(([key,label])=>`<button type="button" class="button ${data.theme===key?'selected':''}" data-theme-choice="${key}" aria-pressed="${data.theme===key}">${label}</button>`).join('')}</div></div><div class="setting-row timezone-setting-row"><div><b>Display timezone</b><p>Used for trade times, reports, and dashboard dates.</p></div><select id="timezone-setting" aria-label="Display timezone">${timezoneOptionsMarkup()}</select></div><div class="setting-row"><div><b>Default account currency</b></div><input id="account-currency" value="${escapeHtml(data.accountCurrency)}" maxlength="8"></div><div class="setting-row"><div><b>Local trades</b><p>Clear saved trades from this browser.</p></div><button class="small-btn danger" id="clear-data">Clear trades</button></div></section>`}
function render(){syncAccountControls();const titles={dashboard:'Dashboard',trades:'Trades',journal:'Journal',analysis:'Analysis',performance:'Performance','trade-analysis':'Trade Analysis',insights:'Trade Insights',calendar:'Economic Calendar',backtesting:'Backtesting',tools:'Connect MT4/MT5','market-tools':'Tools',settings:'Settings'};document.querySelector('#page-title').textContent=titles[activeView]||'Dashboard';const views={dashboard,trades:tradesPage,journal:journalPage,analysis:analysisPage,performance:analysisPage,'trade-analysis':tradeAnalysisPage,insights:tradeInsightsPage,calendar:economicCalendarPage,backtesting:backtestingPage,tools:toolsPage,'market-tools':tradingToolsPage,settings:settingsPage};document.querySelector('#view').innerHTML=(views[activeView]||dashboard)();populatePairLists();wireView();if(activeView==='calendar')loadEconomicCalendar()}
function wireCurveHover(){document.querySelectorAll('[data-curve-chart]').forEach(host=>{const svg=host.querySelector('svg'),tip=host.querySelector('[data-curve-tooltip]'),line=host.querySelector('[data-curve-line]'),dot=host.querySelector('[data-curve-dot]');let points=[],scrubbing=false;try{points=JSON.parse(host.dataset.curvePoints||'[]')}catch{}if(!svg||!tip||!points.length)return;const update=e=>{const rect=svg.getBoundingClientRect(),fraction=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),point=points[Math.round(fraction*(points.length-1))];if(!point)return;line.setAttribute('x1',point.x);line.setAttribute('x2',point.x);line.setAttribute('visibility','visible');dot.setAttribute('cx',point.x);dot.setAttribute('cy',point.y);dot.setAttribute('visibility','visible');const date=new Date(point.date),stamp=Number.isFinite(date.getTime())?date.toLocaleString(undefined,{timeZone:APP_TZ,weekday:'short',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}):'Trade date';host.querySelector('[data-curve-date]').textContent=stamp;host.querySelector('[data-curve-value]').textContent=money(point.value,host.dataset.curveCurrency);const caption=host.dataset.curveCaption;if(caption)host.querySelector('[data-curve-caption]').textContent=caption;const x=Math.max(12,Math.min(88,point.x/980*100)),y=point.y/220*rect.height;tip.style.left=x+'%';tip.style.top=(y<88?Math.min(rect.height-92,y+18):Math.max(6,y-82))+'px';tip.hidden=false};const hide=()=>{if(scrubbing)return;tip.hidden=true;line.setAttribute('visibility','hidden');dot.setAttribute('visibility','hidden')};svg.addEventListener('pointermove',update);svg.addEventListener('pointerdown',e=>{scrubbing=true;svg.setPointerCapture?.(e.pointerId);update(e)});svg.addEventListener('pointerup',e=>{if(scrubbing){scrubbing=false;if(svg.hasPointerCapture?.(e.pointerId))svg.releasePointerCapture(e.pointerId)}});svg.addEventListener('pointercancel',()=>{scrubbing=false;hide()});svg.addEventListener('pointerleave',hide)})}
function wireView(){wireCurveHover();document.querySelectorAll("[data-ledger-select]").forEach(row=>{const select=()=>{selectedLedgerTradeId=row.dataset.ledgerSelect;render()};row.addEventListener("click",event=>{if(!event.target.closest("button"))select()});row.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();select()}})});document.querySelector("[data-ledger-search]")?.addEventListener("input",event=>{ledgerSearch=event.target.value;const position=event.target.selectionStart;render();const input=document.querySelector("[data-ledger-search]");input?.focus();input?.setSelectionRange(position,position)});document.querySelectorAll('[data-journal-select]').forEach(b=>b.onclick=()=>{selectedJournalTradeId=b.dataset.journalSelect;render()});document.querySelectorAll('[data-journal-filter]').forEach(b=>b.onclick=()=>{journalStatusFilter=b.dataset.journalFilter;render()});document.querySelector('[data-journal-search]')?.addEventListener('input',e=>{journalSearch=e.target.value;const pos=e.target.selectionStart;render();const n=document.querySelector('[data-journal-search]');n?.focus();n?.setSelectionRange(pos,pos)});document.querySelector('#account-scope')?.addEventListener('change',e=>{accountScope=e.target.value;data.accountScope=accountScope;save();render()});document.querySelectorAll('[data-dashboard-range]').forEach(b=>b.onclick=()=>{dashboardRange=b.dataset.dashboardRange;render()});document.querySelectorAll('[data-dashboard-mode]').forEach(b=>b.onclick=()=>{dashboardMode=b.dataset.dashboardMode;render()});document.querySelector('[data-bridge-scope]')?.addEventListener('change',e=>{accountScope=e.target.value;data.accountScope=accountScope;save()});document.querySelector('#mt-account-form')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,d=new FormData(f),platform=String(d.get('platform')||'MT5'),accountNumber=String(d.get('accountNumber')||'').trim(),server=String(d.get('server')||'').trim(),name=String(d.get('name')||'').trim();if(!accountNumber||!server||!name){toast('Enter the account name, broker server, and login number');return}const account=registerAccount({platform,accountNumber,server,name,currency:data.accountCurrency,balance:d.get('balance'),source:'MetaTrader bridge',reactivate:true});accountScope=account.id;data.accountScope=accountScope;save();render();toast('Account saved · attach the bridge EA to start syncing')});document.querySelectorAll('[data-set-account-scope]').forEach(b=>b.onclick=()=>{accountScope=b.dataset.setAccountScope;data.accountScope=accountScope;save();render()});document.querySelector('#profile-form')?.addEventListener('submit',saveProfile);document.querySelector('#profile-photo')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file');return}try{profilePhotoDraft=await resizeProfileImage(file);const preview=document.querySelector('#profile-avatar-preview');preview?.replaceChildren();if(preview){const image=document.createElement('img');image.src=profilePhotoDraft;image.alt='';preview.append(image)}}catch{toast('Could not read this image')}});document.querySelector('[data-remove-profile-photo]')?.addEventListener('click',()=>{profilePhotoDraft='';const preview=document.querySelector('#profile-avatar-preview'),name=document.querySelector('#profile-form')?.elements.profileName.value||'M';preview?.replaceChildren();if(preview){const initial=document.createElement('span');initial.textContent=String(name).trim().charAt(0).toUpperCase()||'M';preview.append(initial)}const input=document.querySelector('#profile-photo');if(input)input.value=''});document.querySelector('[data-account-edit]')?.addEventListener('change',e=>{editingAccountId=e.target.value;render()});document.querySelector('#new-account')?.addEventListener('click',()=>{const a=registerAccount({id:`manual:${crypto.randomUUID()}`,name:`New trading account`,platform:'Manual',currency:data.accountCurrency,source:'Manual'});editingAccountId=a.id;save();render()});document.querySelector('#account-edit-form')?.addEventListener('submit',e=>{e.preventDefault();const a=accountById(e.currentTarget.elements.accountId.value);if(!a)return;for(const k of ['name','broker','server','platform','accountNumber','currency'])a[k]=String(e.currentTarget.elements[k].value||'').trim();a.balance=e.currentTarget.elements.balance.value;a.balanceAsOf=e.currentTarget.elements.balanceAsOf.value;if(a.balance!=='')a.balanceSource='manual';editingAccountId=a.id;save();render();toast('Account details saved')});document.querySelectorAll('[data-remove-account]').forEach(b=>b.onclick=()=>startAccountRemoval(b.dataset.removeAccount));document.querySelectorAll('[data-account-removal]').forEach(b=>b.onclick=()=>finishAccountRemoval(b.dataset.accountRemoval==='delete'));document.querySelectorAll('[data-restore-account]').forEach(b=>b.onclick=()=>{const a=accountById(b.dataset.restoreAccount);if(!a)return;a.archived=false;editingAccountId=a.id;save();render();toast('Account restored')});document.querySelectorAll('[data-action="new"]').forEach(b=>b.onclick=()=>openTrade());document.querySelectorAll('[data-action="import"]').forEach(b=>b.onclick=()=>document.querySelector('#import-dialog').showModal());document.querySelectorAll('[data-action="export"]').forEach(b=>b.onclick=openExportDialog);document.querySelector('#export-form')?.addEventListener('submit',exportCsv);document.querySelector('#export-period')?.addEventListener('change',e=>{document.querySelector('#export-date-range').hidden=e.target.value!=='custom'});document.querySelector('#export-account')?.addEventListener('change',syncExportSymbols);document.querySelectorAll('[data-action="report"]').forEach(b=>b.onclick=downloadFullReport);document.querySelectorAll('[data-view-link]').forEach(b=>b.onclick=()=>setView(b.dataset.viewLink));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openTrade(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteTrade(b.dataset.delete));document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{chartRange=b.dataset.range;render()});document.querySelectorAll('[data-trade-filter]').forEach(el=>el.onchange=()=>{tradeFilters[el.dataset.tradeFilter]=el.value;render()});document.querySelector('[data-clear-filters]')?.addEventListener('click',()=>{tradeFilters={status:'all',direction:'all',outcome:'all',from:'',to:''};render()});document.querySelectorAll('[data-performance-period]').forEach(b=>b.onclick=()=>{performanceFilters.period=b.textContent;render()});document.querySelectorAll('[data-performance-outcome]').forEach(b=>b.onclick=()=>{performanceFilters.outcome=b.textContent;render()});document.querySelectorAll('[data-curve]').forEach(b=>b.onclick=()=>{performanceFilters.curve=b.dataset.curve;render()});document.querySelectorAll('[data-select-analysis]').forEach(b=>b.onclick=()=>{selectedAnalysisTradeId=b.dataset.selectAnalysis;render()});document.querySelectorAll('[data-analysis-filter]').forEach(b=>b.onclick=()=>{tradeAnalysisFilter=b.dataset.analysisFilter;render()});document.querySelector('[data-analysis-search]')?.addEventListener('input',e=>{analysisSearch=e.target.value;const pos=e.target.selectionStart;render();const n=document.querySelector('[data-analysis-search]');n.focus();n.setSelectionRange(pos,pos)});document.querySelector('[data-analysis-period]')?.addEventListener('change',e=>{tradeAnalysisPeriod=e.target.value;render()});document.querySelector('#run-backtest')?.addEventListener('click',runBacktest);document.querySelector('#test-symbol')?.addEventListener('input',updateBacktestInputs);document.querySelector('#test-symbol')?.addEventListener('change',loadBridgeCandles);document.querySelector('#ohlc-file')?.addEventListener('change',loadOhlcFile);document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>setTheme(b.dataset.themeChoice));document.querySelector('#account-currency')?.addEventListener('change',e=>{data.accountCurrency=e.target.value.toUpperCase();save();render()});document.querySelector('#timezone-setting')?.addEventListener('change',e=>{if(!validTimeZone(e.target.value))return;APP_TZ=e.target.value;data.timeZone=APP_TZ;save();window.dispatchEvent(new CustomEvent('tradelog:timezone-change',{detail:{timeZone:APP_TZ}}));updateHeaderClock();render()});document.querySelector('#clear-data')?.addEventListener('click',()=>{if(confirm('Clear all trades saved in this browser?')){data.trades=[];save();render()}});document.querySelector('[data-refresh-calendar]')?.addEventListener('click',loadEconomicCalendar);document.querySelector('[data-calendar-currency]')?.addEventListener('change',e=>{calendarCurrency=e.target.value;renderEconomicEvents()});document.querySelector('[data-calendar-impact]')?.addEventListener('change',e=>{calendarImpact=e.target.value;renderEconomicEvents()});document.querySelectorAll('[data-journal-form]').forEach(f=>f.onsubmit=saveJournal);document.querySelectorAll('[data-journal-section-toggle]').forEach(input=>input.addEventListener('change',()=>{const workspace=input.closest('.journal-workspace'),form=workspace?.querySelector('[data-journal-form]'),section=workspace?.querySelector(`[data-journal-section-content="${input.dataset.journalSectionToggle}"]`);if(section)section.hidden=!input.checked;if(form)saveJournalLayout(form)}));document.querySelectorAll('[data-journal-layout-reset]').forEach(button=>button.onclick=()=>{const trade=accountTrades().find(t=>String(t.id)===String(button.dataset.journalLayoutReset));if(trade){trade.journalLayout=null;save();render()}});document.querySelectorAll('.journal-drag-handle').forEach(handle=>handle.addEventListener('dragstart',event=>{draggedJournalSection=handle.closest('[data-journal-arrange-item]')?.dataset.journalArrangeItem||'';event.dataTransfer?.setData('text/plain',draggedJournalSection);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}));document.querySelectorAll('[data-journal-arrange-item]').forEach(item=>{item.addEventListener('dragover',event=>event.preventDefault());item.addEventListener('drop',event=>{event.preventDefault();const sourceId=event.dataTransfer?.getData('text/plain')||draggedJournalSection,targetId=item.dataset.journalArrangeItem,workspace=item.closest('.journal-workspace'),form=workspace?.querySelector('[data-journal-form]'),source=workspace?.querySelector(`[data-journal-arrange-item="${sourceId}"]`),list=item.parentElement,stack=form?.querySelector('.journal-section-stack');if(!source||!form||!stack||!sourceId||sourceId===targetId)return;const ids=[...list.querySelectorAll('[data-journal-arrange-item]')].map(row=>row.dataset.journalArrangeItem),from=ids.indexOf(sourceId),to=ids.indexOf(targetId);if(from<to)list.insertBefore(source,item.nextSibling);else list.insertBefore(source,item);for(const row of list.querySelectorAll('[data-journal-arrange-item]')){const section=stack.querySelector(`[data-journal-section-content="${row.dataset.journalArrangeItem}"]`);if(section)stack.append(section)}saveJournalLayout(form);draggedJournalSection=''})});document.querySelectorAll('[data-add-check]').forEach(b=>b.onclick=()=>addJournalCheck(b));document.querySelectorAll('[data-remove-check]').forEach(b=>b.onclick=()=>b.closest('.journal-check-item').remove());document.querySelectorAll('[data-journal-report]').forEach(b=>b.onclick=()=>downloadJournalReport(b.dataset.journalReport));document.querySelectorAll('[data-clear-photo]').forEach(b=>b.onclick=()=>{const f=b.closest('form');f.dataset.clearPhotos=(f.dataset.clearPhotos||'')+','+b.dataset.clearPhoto;b.closest('.photo-preview').remove()});updateBacktestInputs();if(activeView==='backtesting')loadBridgeCandles();if(activeView==='market-tools')wireTradingTools();loadJournalCharts()}
