function openPrivacyDialog(){const dialog=document.querySelector('#privacy-dialog'),form=document.querySelector('#privacy-form');if(!dialog||!form)return;const configured=Boolean(privacyRecord.verifier&&privacyRecord.salt);privacyDialogMode=!configured?'setup':privacyLocked?'unlock':'lock';form.reset();const confirmWrap=document.querySelector('#privacy-pin-confirm-wrap'),pin=document.querySelector('#privacy-pin');confirmWrap.hidden=privacyDialogMode!=='setup';document.querySelector('#privacy-dialog-title').textContent=privacyDialogMode==='setup'?'Set admin passcode':privacyDialogMode==='unlock'?'Unlock editing':'Lock editing';document.querySelector('#privacy-dialog-copy').textContent=privacyDialogMode==='setup'?'Choose a 6–32 digit code. It will be saved on this browser as a salted verifier.':'Enter your admin passcode to '+(privacyDialogMode==='unlock'?'unlock editing.':'lock editing.');document.querySelector('#privacy-submit').textContent=privacyDialogMode==='setup'?'Set and lock':privacyDialogMode==='unlock'?'Unlock journal':'Lock journal';document.querySelector('#privacy-feedback').textContent='';pin.autocomplete=privacyDialogMode==='setup'?'new-password':'current-password';dialog.showModal();pin.focus()}
async function handlePrivacySubmit(event){event.preventDefault();event.stopImmediatePropagation();const pin=document.querySelector('#privacy-pin').value,feedback=document.querySelector('#privacy-feedback'),dialog=document.querySelector('#privacy-dialog');if(!/^\d{6,32}$/.test(pin)){feedback.textContent='Use 6 to 32 digits.';return}if(!window.crypto?.subtle){feedback.textContent='Secure passcode storage is unavailable in this browser. Open the hosted HTTPS site.';return}try{if(privacyDialogMode==='setup'){if(pin!==document.querySelector('#privacy-pin-confirm').value){feedback.textContent='The passcodes do not match.';return}const salt=crypto.getRandomValues(new Uint8Array(16));privacyRecord={salt:encodeBytes(salt),verifier:await derivePrivacyVerifier(pin,salt),locked:false};if(!persistPrivacyConfig())return;dialog.close();setPrivacyLock(true);toast('Editing locked on this browser');return}const salt=Uint8Array.from(atob(privacyRecord.salt),c=>c.charCodeAt(0)),candidate=await derivePrivacyVerifier(pin,salt);if(candidate!==privacyRecord.verifier){feedback.textContent='That passcode is not correct.';document.querySelector('#privacy-pin').value='';document.querySelector('#privacy-pin').focus();return}const next=privacyDialogMode==='lock';dialog.close();setPrivacyLock(next);toast(next?'Editing locked on this browser':'Editing unlocked on this browser')}catch{feedback.textContent='Could not verify the passcode. Please try again.'}}
const privacyWriteTargets='#timezone-setting,#new-trade,#new-account,#clear-data,#add-instrument,#trade-form,.journal-form,#profile-form,#account-edit-form,#mt-account-form,#account-currency,#csv-file,[data-edit],[data-delete],[data-add-check],[data-remove-check],[data-clear-photo],[data-photo],[data-custom-check-input],[data-journal-layout-reset],[data-remove-account],[data-restore-account],[data-account-removal],[data-remove-inst],[data-remove-profile-photo],[data-theme-choice],[data-cloud-upload],[data-cloud-use-remote],[data-cloud-sync-now]';
document.addEventListener('click',event=>{const target=event.target;if(target.closest('[data-privacy-open]')){event.preventDefault();event.stopImmediatePropagation();openPrivacyDialog();return}if(target.closest('[data-close="privacy-dialog"]')){event.preventDefault();document.querySelector('#privacy-dialog')?.close();return}if(!SHARE_MODE&&privacyLocked&&target.closest(privacyWriteTargets)){event.preventDefault();event.stopImmediatePropagation();toast('Editing is locked. Enter your admin passcode in Settings to unlock.')}},true);
document.addEventListener('submit',event=>{if(event.target.id==='privacy-form'){handlePrivacySubmit(event);return}if(!SHARE_MODE&&privacyLocked&&!event.target.matches('[data-cloud-share-form],[data-cloud-email-form]')){event.preventDefault();event.stopImmediatePropagation();toast('Editing is locked. Enter your admin passcode in Settings to unlock.')}},true);
document.addEventListener('change',event=>{if(!SHARE_MODE&&privacyLocked&&event.target.closest(privacyWriteTargets)){event.preventDefault();event.stopImmediatePropagation()}},true);
document.addEventListener('input',event=>{if(!SHARE_MODE&&privacyLocked&&event.target.closest(privacyWriteTargets)){event.preventDefault();event.stopImmediatePropagation()}},true);
document.addEventListener('click',event=>{const button=event.target.closest('[data-dashboard-utility]');if(!button)return;selectedUtility=button.dataset.dashboardUtility;setView('market-tools')});

// Ease the full-screen spotlight behind the pointer, independently of the card lens above.
const cursorSpotlight=document.querySelector('#cursor-spotlight');let spotlightFrame=0,spotlightX=-1000,spotlightY=-1000,spotlightTargetX=-1000,spotlightTargetY=-1000,spotlightLastTime=0;function drawCursorSpotlight(now){spotlightFrame=0;if(!cursorSpotlight?.classList.contains('is-visible'))return;const delta=Math.min((now-spotlightLastTime)/1000,1/30);spotlightLastTime=now;const k=pointerMotion.matches?1:1-Math.exp(-delta*12);spotlightX+=(spotlightTargetX-spotlightX)*k;spotlightY+=(spotlightTargetY-spotlightY)*k;cursorSpotlight.style.setProperty('--spotlight-x',`${spotlightX}px`);cursorSpotlight.style.setProperty('--spotlight-y',`${spotlightY}px`);if(Math.abs(spotlightTargetX-spotlightX)>.25||Math.abs(spotlightTargetY-spotlightY)>.25)spotlightFrame=requestAnimationFrame(drawCursorSpotlight)}document.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||!cursorSpotlight)return;spotlightTargetX=e.clientX;spotlightTargetY=e.clientY;spotlightLastTime=performance.now();cursorSpotlight.classList.add('is-visible');if(pointerMotion.matches){spotlightX=spotlightTargetX;spotlightY=spotlightTargetY;cursorSpotlight.style.setProperty('--spotlight-x',`${spotlightX}px`);cursorSpotlight.style.setProperty('--spotlight-y',`${spotlightY}px`)}else if(!spotlightFrame)spotlightFrame=requestAnimationFrame(drawCursorSpotlight)},{passive:true});window.addEventListener('pointerleave',()=>cursorSpotlight?.classList.remove('is-visible'));window.addEventListener('blur',()=>cursorSpotlight?.classList.remove('is-visible'));
